CREATE DATABASE supply_chain_intelligence;

USE supply_chain_intelligence;
CREATE TABLE supply_chain_master (
    country VARCHAR(100),
    country_code VARCHAR(10),
    year INT,
    gdp_usd DOUBLE NULL,
    exports_pct_gdp DOUBLE NULL,
    gdp_growth_pct DOUBLE NULL,
    inflation_pct DOUBLE NULL,
    population_total BIGINT,
    total_trade_records DOUBLE NULL,
    tariffline_total_records DOUBLE NULL,
    lpi_score DOUBLE NULL
);



SELECT COUNT(*) AS total_rows
FROM supply_chain_master;

SELECT DATABASE();

SELECT COUNT(*) AS total_rows;

SELECT @@autocommit;
SELECT* FROM supply_chain_master;

TRUNCATE TABLE supply_chain_master;

-- Question: Which countries are the most attractive markets for supply-chain expansion based on strong GDP growth, high trade activity, and good logistics performance?
SELECT
    country,
    ROUND(AVG(gdp_growth_pct), 2) AS avg_gdp_growth,
    SUM(total_trade_records) AS total_trade_activity,
    ROUND(AVG(lpi_score), 2) AS avg_lpi
FROM Supply_chain_master
WHERE gdp_growth_pct IS NOT NULL
  AND total_trade_records IS NOT NULL
  AND lpi_score IS NOT NULL
GROUP BY country
HAVING AVG(gdp_growth_pct) > 4
   AND AVG(lpi_score) >= 3
ORDER BY avg_gdp_growth DESC,
         total_trade_activity DESC,
         avg_lpi DESC;

-- Question: Which countries experienced declining economic growth while inflation increased?
WITH yearly_change AS (
    SELECT
        country,
        year,
        gdp_growth_pct,
        inflation_pct,

        LAG(inflation_pct) OVER (
            PARTITION BY country
            ORDER BY year
        ) AS previous_inflation,

        LAG(gdp_growth_pct) OVER (
            PARTITION BY country
            ORDER BY year
        ) AS previous_growth

    FROM Supply_chain_master
)

SELECT
    country,
    year,
    gdp_growth_pct,
    previous_growth,
    inflation_pct,
    previous_inflation
FROM yearly_change
WHERE gdp_growth_pct < previous_growth
  AND inflation_pct > previous_inflation
ORDER BY country, year;

-- Question: Which countries have maintained strong trade activity despite below-average logistics performance?

WITH global_lpi AS (
    SELECT AVG(lpi_score) AS avg_global_lpi
    FROM Supply_chain_master
    WHERE lpi_score IS NOT NULL
),

country_trade AS (
    SELECT
        country,
        SUM(total_trade_records) AS total_trade
    FROM Supply_chain_master
    WHERE total_trade_records IS NOT NULL
    GROUP BY country
)

SELECT
    ct.country,
    ct.total_trade,
    ROUND(AVG(s.lpi_score), 2) AS avg_lpi
FROM country_trade ct
JOIN Supply_chain_master s
    ON ct.country = s.country
CROSS JOIN global_lpi
WHERE s.lpi_score IS NOT NULL
GROUP BY ct.country, ct.total_trade, global_lpi.avg_global_lpi
HAVING AVG(s.lpi_score) < global_lpi.avg_global_lpi
ORDER BY ct.total_trade DESC;

-- Question: Which countries have the highest combination of export dependency and inflation risk?
SELECT
    country,
    ROUND(AVG(exports_pct_gdp), 2) AS avg_export_dependency,
    ROUND(AVG(inflation_pct), 2) AS avg_inflation
FROM Supply_chain_master
WHERE exports_pct_gdp IS NOT NULL
  AND inflation_pct IS NOT NULL
GROUP BY country
HAVING AVG(exports_pct_gdp) > 50
   AND AVG(inflation_pct) > 7
ORDER BY avg_export_dependency DESC,
         avg_inflation DESC;
         
 -- Question: Which countries have relatively small GDP but exceptionally high export intensity?    
 
 WITH country_stats AS (
    SELECT
        country,
        AVG(gdp_usd) AS avg_gdp,
        AVG(exports_pct_gdp) AS avg_exports
    FROM Supply_chain_master
    WHERE gdp_usd IS NOT NULL
      AND exports_pct_gdp IS NOT NULL
    GROUP BY country
),

gdp_threshold AS (
    SELECT
        AVG(avg_gdp) AS global_avg_gdp
    FROM country_stats
)

SELECT
    cs.country,
    ROUND(cs.avg_gdp, 0) AS avg_gdp,
    ROUND(cs.avg_exports, 2) AS avg_export_dependency
FROM country_stats cs
CROSS JOIN gdp_threshold gt
WHERE cs.avg_gdp < gt.global_avg_gdp
  AND cs.avg_exports > 70
ORDER BY cs.avg_exports DESC;

-- Question: Which countries have strong logistics performance but relatively low trade activity?

WITH country_data AS (
    SELECT
        country,
        AVG(lpi_score) AS avg_lpi,
        SUM(total_trade_records) AS total_trade
    FROM Supply_chain_master
    WHERE lpi_score IS NOT NULL
      AND total_trade_records IS NOT NULL
    GROUP BY country
),

trade_benchmark AS (
    SELECT AVG(total_trade) AS avg_trade
    FROM country_data
)

SELECT
    cd.country,
    ROUND(cd.avg_lpi, 2) AS avg_lpi,
    cd.total_trade
FROM country_data cd
CROSS JOIN trade_benchmark tb
WHERE cd.avg_lpi >= 3.5
  AND cd.total_trade < tb.avg_trade
ORDER BY cd.avg_lpi DESC;

-- Question: Which countries have the greatest gap between economic potential and logistics capability?
WITH benchmarks AS (
    SELECT
        AVG(gdp_growth_pct) AS avg_growth,
        AVG(lpi_score) AS avg_lpi
    FROM Supply_chain_master
    WHERE gdp_growth_pct IS NOT NULL
      AND lpi_score IS NOT NULL
)

SELECT
    s.country,
    ROUND(AVG(s.gdp_growth_pct), 2) AS avg_growth,
    ROUND(AVG(s.lpi_score), 2) AS avg_lpi,

    ROUND(
        AVG(s.gdp_growth_pct) - b.avg_growth,
        2
    ) AS growth_advantage,

    ROUND(
        b.avg_lpi - AVG(s.lpi_score),
        2
    ) AS logistics_gap

FROM Supply_chain_master s
CROSS JOIN benchmarks b
WHERE s.gdp_growth_pct IS NOT NULL
  AND s.lpi_score IS NOT NULL

GROUP BY s.country, b.avg_growth, b.avg_lpi

HAVING AVG(s.gdp_growth_pct) > b.avg_growth
   AND AVG(s.lpi_score) < b.avg_lpi

ORDER BY logistics_gap DESC;

-- Question: Which countries remained economically resilient by maintaining positive GDP growth despite high inflation?

SELECT
    country,
    ROUND(AVG(gdp_growth_pct), 2) AS avg_growth,
    ROUND(AVG(inflation_pct), 2) AS avg_inflation,
    COUNT(*) AS years_observed
FROM Supply_chain_master
WHERE gdp_growth_pct IS NOT NULL
  AND inflation_pct IS NOT NULL
GROUP BY country
HAVING AVG(gdp_growth_pct) > 2
   AND AVG(inflation_pct) > 7
ORDER BY avg_growth DESC;

-- Question: Which countries represent the highest overall supply-chain risk when economic instability, inflation, export dependency, and logistics weakness are considered together?
SELECT
    country,

    ROUND(AVG(gdp_growth_pct), 2) AS avg_growth,
    ROUND(AVG(inflation_pct), 2) AS avg_inflation,
    ROUND(AVG(exports_pct_gdp), 2) AS avg_exports,
    ROUND(AVG(lpi_score), 2) AS avg_lpi,

    (
        CASE
            WHEN AVG(gdp_growth_pct) < 0 THEN 30
            WHEN AVG(gdp_growth_pct) < 2 THEN 20
            WHEN AVG(gdp_growth_pct) < 4 THEN 10
            ELSE 0
        END

        +

        CASE
            WHEN AVG(inflation_pct) >= 15 THEN 30
            WHEN AVG(inflation_pct) >= 10 THEN 20
            WHEN AVG(inflation_pct) >= 7 THEN 10
            ELSE 0
        END

        +

        CASE
            WHEN AVG(exports_pct_gdp) >= 100 THEN 20
            WHEN AVG(exports_pct_gdp) >= 70 THEN 15
            WHEN AVG(exports_pct_gdp) >= 50 THEN 10
            ELSE 0
        END

        +

        CASE
            WHEN AVG(lpi_score) < 2 THEN 20
            WHEN AVG(lpi_score) < 3 THEN 15
            WHEN AVG(lpi_score) < 3.5 THEN 10
            ELSE 0
        END

    ) AS supply_chain_risk_score

FROM Supply_chain_master

WHERE gdp_growth_pct IS NOT NULL
  AND inflation_pct IS NOT NULL
  AND exports_pct_gdp IS NOT NULL
  AND lpi_score IS NOT NULL

GROUP BY country

ORDER BY supply_chain_risk_score DESC;

-- Question: Which countries should global companies prioritize for supply-chain investment considering growth, trade, inflation, exports, and logistics together?

SELECT
    country,

    ROUND(AVG(gdp_growth_pct), 2) AS avg_growth,
    ROUND(AVG(exports_pct_gdp), 2) AS avg_exports,
    ROUND(AVG(inflation_pct), 2) AS avg_inflation,
    ROUND(AVG(lpi_score), 2) AS avg_lpi,
    SUM(total_trade_records) AS total_trade,

    (
        CASE
            WHEN AVG(gdp_growth_pct) >= 5 THEN 30
            WHEN AVG(gdp_growth_pct) >= 3 THEN 20
            WHEN AVG(gdp_growth_pct) >= 1 THEN 10
            ELSE 0
        END

        +

        CASE
            WHEN AVG(lpi_score) >= 4 THEN 30
            WHEN AVG(lpi_score) >= 3.5 THEN 20
            WHEN AVG(lpi_score) >= 3 THEN 10
            ELSE 0
        END

        +

        CASE
            WHEN SUM(total_trade_records) >
                 (SELECT AVG(country_trade)
                  FROM (
                      SELECT SUM(total_trade_records) AS country_trade
                      FROM Supply_chain_master
                      GROUP BY country
                  ) x)
            THEN 20
            ELSE 10
        END

        +

        CASE
            WHEN AVG(inflation_pct) < 4 THEN 20
            WHEN AVG(inflation_pct) < 7 THEN 10
            ELSE 0
        END
    ) AS investment_score

FROM Supply_chain_master

WHERE gdp_growth_pct IS NOT NULL
  AND inflation_pct IS NOT NULL
  AND lpi_score IS NOT NULL
  AND total_trade_records IS NOT NULL

GROUP BY country

ORDER BY investment_score DESC;